INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4100, 'management report', '/ˈmænɪdʒmənt rɪˈpɔːrt/', 'noun', '{"zh-TW":["管理報告"],"en":["a periodic report prepared for internal use by management"]}', NULL, 'prepare a management report / review the management report', '[{"en":"Management reports are prepared monthly to track performance.","zh-TW":"管理報告每月編制以追蹤業績。"},{"en":"The management report highlighted the need to cut discretionary spending.","zh-TW":"管理報告強調了需要削減可裁量支出。"}]', NULL, NULL, 5, 4100, NULL),
(4101, 'management team', '/ˈmænɪdʒmənt tiːm/', 'noun', '{"zh-TW":["管理團隊"],"en":["the group of senior leaders responsible for running an organization"]}', NULL, 'strengthen the management team / management team presentation', '[{"en":"A strong management team is essential for sustained business growth.","zh-TW":"強大的管理團隊對持續的業務增長至關重要。"},{"en":"The management team presented a turnaround plan to the board.","zh-TW":"管理團隊向董事會提交了扭轉計劃。"}]', NULL, NULL, 5, 4101, NULL),
(4102, 'manager', '/ˈmænɪdʒər/', 'noun', '{"zh-TW":["經理；管理者"],"en":["a person responsible for controlling a team or department"]}', NULL, 'line manager / senior manager / project manager / account manager', '[{"en":"She reported directly to the regional manager.","zh-TW":"她直接向區域經理匯報。"},{"en":"The manager held weekly team meetings to review progress.","zh-TW":"經理每週召開團隊會議審查進度。"}]', '{"plural":"managers","verb":"manage"}', NULL, 3, 4102, NULL),
(4103, 'managerial', '/ˌmænɪˈdʒɪəriəl/', 'adjective', '{"zh-TW":["管理的；經營的"],"en":["relating to the role or work of managing an organization"]}', NULL, 'managerial skills / managerial position / managerial responsibility', '[{"en":"Strong managerial skills are required for the team leader role.","zh-TW":"團隊領導角色需要強大的管理技能。"},{"en":"She was promoted to a managerial position after two years.","zh-TW":"她在兩年後晉升到了管理職位。"}]', '{"adverb":"managerially","noun":"manager"}', NULL, 4, 4103, NULL),
(4104, 'managing director', '/ˈmænɪdʒɪŋ dɪˈrektər/', 'noun', '{"zh-TW":["董事總經理；管理總監"],"en":["the senior executive responsible for running a company or division"]}', NULL, 'appoint a managing director / role of managing director', '[{"en":"The managing director oversees all company operations.","zh-TW":"董事總經理監督所有公司運營。"},{"en":"She was named managing director of the Asia-Pacific division.","zh-TW":"她被任命為亞太區董事總經理。"}]', '{"abbreviation":"MD","plural":"managing directors"}', NULL, 5, 4104, NULL),
(4105, 'mandate', '/ˈmændeɪt/', 'noun, verb', '{"zh-TW":["授權；命令","授權；強制要求"],"en":["authority given to act; an official order","to require something officially"]}', NULL, 'government mandate / mandate compliance', '[{"en":"The new regulation mandates regular safety inspections.","zh-TW":"新法規要求定期進行安全檢查。"},{"en":"The president received a clear mandate from voters.","zh-TW":"總統從選民那裡獲得了明確的授權。"}]', '{"noun":"mandate","adjective":"mandatory","verb":"mandate"}', NULL, 3, 4105, NULL),
(4106, 'mandatory', '/ˈmændətɔːri/', 'adjective', '{"zh-TW":["強制的；必須的"],"en":["required by law or rules"]}', NULL, 'mandatory training/requirement/retirement', '[{"en":"Safety training is mandatory for all employees.","zh-TW":"安全培訓對所有員工是強制性的。"},{"en":"The company introduced mandatory overtime.","zh-TW":"公司實行了強制加班。"}]', '{"noun":"mandate","adjective":"mandatory","verb":"mandate"}', NULL, 3, 4106, 888),
(4107, 'mandatory disclosure', '/ˈmændətəri dɪsˈkloʊʒər/', 'noun', '{"zh-TW":["強制披露"],"en":["information that must legally be disclosed to regulators or the public"]}', NULL, 'comply with mandatory disclosure / mandatory disclosure requirement', '[{"en":"All listed companies must make mandatory disclosure of material events.","zh-TW":"所有上市公司必須強制披露重大事件。"},{"en":"Failure to make mandatory disclosure can result in regulatory penalties.","zh-TW":"未能進行強制披露可能導致監管處罰。"}]', NULL, NULL, 5, 4107, NULL),
(4108, 'manifest', '/ˈmænɪfest/', 'verb, adjective', '{"zh-TW":["表明；顯示","明顯的"],"en":["to show or demonstrate clearly","obvious"]}', NULL, 'manifest itself / manifest in', '[{"en":"Stress can manifest itself in various physical symptoms.","zh-TW":"壓力可以通過各種身體症狀表現出來。"},{"en":"The problems manifested during the testing phase.","zh-TW":"問題在測試階段顯現出來。"}]', '{"noun":"manifestation","verb":"manifest","adjective":"manifest"}', NULL, 3, 4108, NULL),
(4109, 'manifesto', '/ˌmænɪˈfestəʊ/', 'noun', '{"zh-TW":["宣言；政綱"],"en":["a public declaration of policy and aims"]}', NULL, 'publish a manifesto / election manifesto / party manifesto', '[{"en":"The opposition party''s election manifesto promised tax cuts and public spending reform.","zh-TW":"反對黨的競選政綱承諾減稅和公共開支改革。"},{"en":"The environmental group released a manifesto calling for urgent climate action.","zh-TW":"環保團體發布了一份呼籲採取緊迫氣候行動的宣言。"}]', NULL, NULL, 3, 4109, NULL),
(4110, 'manipulate', '/məˈnɪpjuleɪt/', 'verb', '{"zh-TW":["操縱；操控"],"en":["to control or influence skillfully, often unfairly"]}', NULL, 'manipulate data/figures/people', '[{"en":"He was accused of manipulating financial data.","zh-TW":"他被指控操縱財務數據。"},{"en":"The software allows you to manipulate images easily.","zh-TW":"該軟體允許你輕鬆操作圖像。"}]', '{"noun":"manipulation, manipulator","verb":"manipulate","adjective":"manipulative"}', NULL, 4, 4110, NULL),
(4111, 'manner', '/ˈmænər/', 'noun', '{"zh-TW":["方式；態度；禮貌"],"en":["the way something is done; behavior"]}', NULL, 'in a professional manner / in this manner', '[{"en":"Please handle all complaints in a professional manner.","zh-TW":"請以專業的方式處理所有投訴。"},{"en":"His manner was calm and reassuring.","zh-TW":"他的態度冷靜而令人放心。"}]', '{"noun":"manner, manners","adjective":"mannered"}', NULL, 2, 4111, NULL),
(4112, 'manpower planning', '/ˈmænpaʊər ˈplænɪŋ/', 'noun', '{"zh-TW":["人力規劃"],"en":["the process of forecasting and meeting future staffing requirements"]}', NULL, 'conduct manpower planning / manpower planning forecast', '[{"en":"Manpower planning ensured adequate staffing for the new plant opening.","zh-TW":"人力規劃確保了新工廠開業的充足人員配置。"},{"en":"Effective manpower planning aligns recruitment with business growth projections.","zh-TW":"有效的人力規劃使招募與業務增長預測保持一致。"}]', '{"synonym":"workforce planning","synonym2":"human resource planning"}', NULL, 5, 4112, NULL),
(4113, 'manual', '/ˈmænjuəl/', 'noun, adjective', '{"zh-TW":["手冊；說明書","手動的；體力的"],"en":["a handbook; a book of instructions","done by hand; physical"]}', NULL, 'user/instruction manual / manual labor', '[{"en":"Please refer to the user manual for setup instructions.","zh-TW":"請參閱使用手冊了解安裝說明。"},{"en":"The process was switched from manual to automated.","zh-TW":"流程從手動改為自動化。"}]', '{"noun":"manual","adjective":"manual","adverb":"manually"}', NULL, 2, 4113, NULL),
(4114, 'manufacture', '/ˌmænjuˈfæktʃər/', 'verb', '{"zh-TW":["製造","製造；生產"],"en":["to make goods in large quantities by machinery","to make goods in large quantities"]}', '{"root":{"text":"manu","meaning":"hand (手)"},"suffix":{"text":"facture","meaning":"make (製造)"},"logic":"用手製造，現指大規模製造。"}', 'manufacture products / manufacturing industry; manufacture products/goods/components', '[{"en":"The company manufactures electronic components.","zh-TW":"公司製造電子零件。"},{"en":"Most of these goods are manufactured in China.","zh-TW":"這些商品大多在中國製造。"},{"en":"The company manufactures electronic components.","zh-TW":"該公司製造電子零件。"},{"en":"Most of their products are manufactured overseas.","zh-TW":"他們大部分產品都在海外製造。"}]', '{"noun":"manufacturer","noun2":"manufacturing","verb":"manufacture"}', NULL, 4, 4114, 38),
(4115, 'manuscript', '/ˈmænjuskrɪpt/', 'noun', '{"zh-TW":["手稿；原稿"],"en":["an author''s text that has not yet been published"]}', NULL, 'submit a manuscript / manuscript review', '[{"en":"The author submitted the manuscript to the publisher.","zh-TW":"作者向出版社提交了手稿。"},{"en":"The manuscript was reviewed by three experts.","zh-TW":"手稿由三位專家審閱。"}]', '{"noun":"manuscript"}', NULL, 4, 4115, NULL),
(4116, 'map', '/mæp/', 'noun', '{"zh-TW":["地圖；規劃"],"en":["a drawing of an area","to plan in detail"]}', NULL, 'road map / map out', '[{"en":"We mapped out our strategy for next year.","zh-TW":"我們規劃了明年的策略。"},{"en":"Here is the road map for the project.","zh-TW":"這是專案的路線圖。"}]', '{"noun":"map","verb":"map","noun2":"mapping"}', NULL, 1, 4116, NULL),
(4117, 'marathon', '/ˈmærəθɒn/', 'noun', '{"zh-TW":["馬拉松"],"en":["a long-distance running race of 42.195 km"]}', NULL, 'run a marathon / marathon runner', '[{"en":"She completed her first marathon.","zh-TW":"她完成了她的第一場馬拉松。"},{"en":"Training for a marathon takes months.","zh-TW":"馬拉松訓練需要數月時間。"}]', NULL, NULL, 3, 4117, NULL),
(4118, 'marbling', '/''mɑːrblɪŋ/', 'noun', '{"zh-TW":["油花；大理石紋"],"en":["the distribution of fat within meat that influences its flavor and tenderness"]}', NULL, 'good marbling / well-marbled / marbling grade', '[{"en":"Wagyu beef is prized for its exceptional marbling and rich flavor.","zh-TW":"和牛因其卓越的油花和豐富的風味而備受推崇。"},{"en":"Higher marbling in steak generally means juicier, more flavorful meat.","zh-TW":"牛排中較高的油花通常意味著更多汁、更有風味的肉質。"}]', NULL, NULL, 3, 4118, NULL),
(4119, 'margin', '/ˈmɑːrdʒɪn/', 'noun', '{"zh-TW":["邊緣；利潤率；差額"],"en":["the edge of something; the amount of profit"]}', NULL, 'profit margin / by a narrow margin / margin of error', '[{"en":"The company''s profit margin increased to 15%.","zh-TW":"公司的利潤率增至15%。"},{"en":"He won the election by a narrow margin.","zh-TW":"他以微弱的差距贏得了選舉。"}]', '{"noun":"margin","adjective":"marginal","adverb":"marginally"}', NULL, 2, 4119, 390),
(4120, 'margin call', '/ˈmɑːrdʒɪn kɔːl/', 'noun', '{"zh-TW":["追加保證金通知；補倉通知"],"en":["a demand to deposit more funds when a leveraged position falls below minimum"]}', NULL, 'receive a margin call / trigger a margin call', '[{"en":"The investor received a margin call as the stock price fell sharply.","zh-TW":"隨著股價急劇下跌，投資者收到了補倉通知。"},{"en":"Failing to meet a margin call results in forced liquidation.","zh-TW":"未能滿足補倉通知將導致強制平倉。"}]', NULL, NULL, 4, 4120, NULL),
(4121, 'margin compression', '/ˈmɑːrdʒɪn kəmˈpreʃən/', 'noun', '{"zh-TW":["利潤壓縮"],"en":["a reduction in the profit margin of a business"]}', NULL, 'experience margin compression / fight margin compression / margin compression trend', '[{"en":"Rising input costs led to significant margin compression for manufacturers.","zh-TW":"原料成本上漲導致製造商的利潤大幅壓縮。"},{"en":"Price competition often causes margin compression across industries.","zh-TW":"價格競爭往往導致行業普遍的利潤壓縮。"}]', NULL, NULL, 5, 4121, NULL),
(4122, 'marginal cost', '/ˈmɑːrdʒɪnəl kɒst/', 'noun', '{"zh-TW":["邊際成本"],"en":["the additional cost of producing one more unit of a product"]}', NULL, 'calculate marginal cost / minimize marginal cost', '[{"en":"Marginal cost decreases as production volume rises due to fixed cost spreading.","zh-TW":"由於固定成本分攤，邊際成本隨著生產量增加而降低。"},{"en":"Pricing below marginal cost is not sustainable in the long run.","zh-TW":"長期來看，定價低於邊際成本是不可持續的。"}]', '{"synonym":"incremental cost"}', NULL, 5, 4122, NULL),
(4123, 'marginalization', '/ˌmɑːrdʒɪnəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["邊緣化"],"en":["the process of treating a person or group as insignificant or peripheral"]}', NULL, 'economic marginalization / social marginalization / prevent marginalization', '[{"en":"Marginalization of minority communities perpetuates cycles of poverty.","zh-TW":"少數族裔社區的邊緣化使貧困循環持續。"},{"en":"Policy interventions aim to reverse the marginalization of rural populations.","zh-TW":"政策干預旨在逆轉農村人口的邊緣化。"}]', '{"verb":"marginalize","adjective":"marginalized"}', NULL, 5, 4123, NULL),
(4124, 'marina', '/''məˈriːnə/', 'noun', '{"zh-TW":["遊艇停泊處；小艇碼頭"],"en":["a harbor with facilities for yachts and small boats"]}', NULL, 'yacht marina / stay at a marina / marina facilities', '[{"en":"The marina could accommodate over three hundred boats.","zh-TW":"這個遊艇停泊處可以容納三百多艘船隻。"},{"en":"We dined at a restaurant overlooking the marina at sunset.","zh-TW":"我們在日落時分在俯瞰遊艇停泊處的餐廳用餐。"}]', NULL, NULL, 2, 4124, NULL),
(4125, 'marinade', '/''mærɪneɪd/', 'noun', '{"zh-TW":["醃料；醃汁"],"en":["a mixture of oil, vinegar, spices, and herbs used to flavor or tenderize food before cooking"]}', NULL, 'prepare a marinade / marinate in / spicy marinade', '[{"en":"The chicken was left in a garlic and herb marinade overnight.","zh-TW":"雞肉在大蒜和香草醃料中醃製了一夜。"},{"en":"A good marinade adds depth of flavor to grilled meats and vegetables.","zh-TW":"好的醃料為烤肉和蔬菜增添了豐富的風味。"}]', '{"verb":"marinate"}', NULL, 3, 4125, NULL),
(4126, 'marinate', '/''mærɪneɪt/', 'verb', '{"zh-TW":["醃製；浸泡醃料"],"en":["to soak food in a marinade before cooking to add flavor or tenderize"]}', NULL, 'marinate overnight / marinate for an hour / marinate in spices', '[{"en":"She marinated the tofu in soy sauce and ginger for an hour.","zh-TW":"她將豆腐在醬油和薑中醃製了一個小時。"},{"en":"Marinating the meat overnight resulted in a more tender and flavorful dish.","zh-TW":"將肉醃製一夜，使菜肴更加嫩滑和美味。"}]', '{"noun":"marinade"}', NULL, 3, 4126, NULL),
(4127, 'marine conservation', '/məˈriːn ˌkɒnsəˈveɪʃən/', 'noun', '{"zh-TW":["海洋保育"],"en":["the protection and preservation of marine ecosystems and biodiversity"]}', NULL, 'marine conservation efforts / marine conservation policy / support marine conservation', '[{"en":"Marine conservation protects fisheries and coastal communities.","zh-TW":"海洋保育保護漁業和沿海社區。"},{"en":"Establishing marine protected areas is a key marine conservation strategy.","zh-TW":"建立海洋保護區是海洋保育的關鍵策略。"}]', NULL, NULL, 5, 4127, NULL),
(4128, 'maritime', '/ˈmærɪtaɪm/', 'adjective', '{"zh-TW":["海事的；海運的"],"en":["relating to the sea or shipping"]}', NULL, 'maritime law/industry/trade', '[{"en":"Maritime trade accounts for 80% of global commerce.","zh-TW":"海運貿易佔全球商業的80%。"},{"en":"Maritime law governs shipping disputes.","zh-TW":"海事法管轄航運糾紛。"}]', '{"noun":"maritime","adjective":"maritime"}', NULL, 3, 4128, NULL),
(4129, 'mark', '/mɑːrk/', 'noun', '{"zh-TW":["【主要意義-動詞/名詞】標記；記號","【次要意義-動詞】留意；注意（尤其在命令句中）","【次要意義-名詞】成績；分數","【次要意義-動詞】紀念；標誌著（事件）"],"en":["[primary] to make a visible sign; a visible sign","[secondary - verb] to notice and remember something (especially in imperatives)","[secondary - noun] a score or grade in academic work","[secondary - verb] to commemorate; to indicate an important event"]}', NULL, 'mark my words / mark an occasion / up to the mark / on your mark / benchmark', '[{"en":"Mark my words, this policy will cause serious problems.","zh-TW":"請記住我的話，這項政策將引發嚴重問題。"},{"en":"The ceremony marks the 50th anniversary of the company.","zh-TW":"這個儀式標誌著公司成立50週年。"},{"en":"The new product launch marks a turning point in the company history.","zh-TW":"新產品的發布標誌著公司歷史的轉折點。"}]', '{"noun":"marker, marking, benchmark","adjective":"marked"}', 'mark my words（請記住我的話）、mark an occasion（紀念某場合）、marked improvement（顯著的改善）均為 TOEIC 常見用法，動詞 mark = 「標誌著/紀念」在公司周年文章中常見。', 1, 4129, NULL),
(4130, 'mark to market', '/mɑːrk tə ˈmɑːrkɪt/', 'verb', '{"zh-TW":["按市值計算；盯市"],"en":["to value an asset at its current market price rather than its book or historical cost"]}', NULL, 'mark assets to market / mark-to-market accounting / fair value mark to market', '[{"en":"Banks are required to mark their securities portfolios to market at the end of each quarter.","zh-TW":"銀行被要求在每個季度末按市值計算其證券投資組合。"},{"en":"Mark-to-market accounting caused significant volatility in reported earnings during the crisis.","zh-TW":"盯市會計在危機期間導致已報告收益出現重大波動。"}]', NULL, NULL, 5, 4130, NULL),
(4131, 'mark-to-market', '/mɑːrk tə ˈmɑːrkɪt/', 'verb', '{"zh-TW":["按市價計算；市值計算"],"en":["to revalue an asset at its current market price rather than its original cost"]}', NULL, 'mark-to-market valuation / mark-to-market accounting', '[{"en":"The portfolio is revalued daily using mark-to-market accounting.","zh-TW":"投資組合使用市值計算每日重新估值。"},{"en":"Mark-to-market accounting increases transparency but adds volatility.","zh-TW":"市值計算會計增加了透明度，但也增加了波動性。"}]', NULL, NULL, 5, 4131, NULL),
(4132, 'market', '/ˈmɑːrkɪt/', 'noun, verb', '{"zh-TW":["市場","推銷；銷售"],"en":["a place where goods are sold; demand for goods","to advertise and sell"]}', NULL, 'market share / target market / market research', '[{"en":"We need to conduct market research before launching.","zh-TW":"我們需要在推出前進行市場調查。"},{"en":"The product was successfully marketed to young professionals.","zh-TW":"該產品成功地向年輕專業人士推銷。"}]', '{"noun":"market, marketing, marketer","verb":"market","adjective":"marketable"}', NULL, 2, 4132, NULL),
(4133, 'market access', '/ˈmɑːrkɪt ˈækses/', 'noun', '{"zh-TW":["市場進入；市場准入"],"en":["the ability of a company to enter and operate in a particular market"]}', NULL, 'gain market access / restrict market access', '[{"en":"The trade deal improved market access for foreign companies.","zh-TW":"貿易協議改善了外國公司的市場准入。"},{"en":"Local partners can help provide market access in new regions.","zh-TW":"本地合作夥伴可以幫助在新地區提供市場准入。"}]', NULL, NULL, 5, 4133, NULL),
(4134, 'market analysis', '/ˈmɑːrkɪt əˈnælɪsɪs/', 'noun', '{"zh-TW":["市場分析"],"en":["a quantitative and qualitative assessment of a market"]}', NULL, 'competitive market analysis / market analysis report / conduct market analysis', '[{"en":"The market analysis identified a gap in the mid-range product segment.","zh-TW":"市場分析識別了中端產品市場的空缺。"},{"en":"Regular market analysis helps businesses stay ahead of trends.","zh-TW":"定期市場分析幫助企業保持領先趨勢。"}]', NULL, NULL, 5, 4134, NULL),
(4135, 'market capitalization', '/ˈmɑːrkɪt ˌkæpɪtlɪˈzeɪʃən/', 'noun', '{"zh-TW":["市值"],"en":["the total market value of a company''s outstanding shares"]}', NULL, 'large-cap / mid-cap / market capitalization of / calculate market cap', '[{"en":"The company''s market capitalization exceeded $100 billion.","zh-TW":"公司市值超過1000億美元。"},{"en":"Market capitalization is calculated by multiplying share price by shares outstanding.","zh-TW":"市值通過股價乘以流通股數來計算。"}]', '{"abbreviation":"market cap"}', NULL, 5, 4135, NULL),
(4136, 'market correction', '/ˈmɑːrkɪt kəˈrekʃən/', 'noun', '{"zh-TW":["市場修正；股市回調"],"en":["a decline of 10% or more in a security or market index from recent highs"]}', NULL, 'enter market correction territory / trigger a market correction', '[{"en":"The market correction wiped out gains made in the previous quarter.","zh-TW":"市場修正抹去了上一季的漲幅。"},{"en":"Analysts predicted a market correction after the rapid rally.","zh-TW":"分析師在快速上漲後預測市場將出現修正。"}]', NULL, NULL, 5, 4136, NULL),
(4137, 'market dynamics', '/ˈmɑːrkɪt daɪˈnæmɪks/', 'noun', '{"zh-TW":["市場動態"],"en":["the forces that affect supply and demand in a market"]}', NULL, 'understand market dynamics / respond to market dynamics', '[{"en":"Changing market dynamics required a shift in the company strategy.","zh-TW":"不斷變化的市場動態要求公司策略做出改變。"},{"en":"Technology is reshaping market dynamics across industries.","zh-TW":"技術正在重塑各行業的市場動態。"}]', NULL, NULL, 5, 4137, NULL),
(4138, 'market economy', '/ˈmɑːrkɪt ɪˈkɒnəmi/', 'noun', '{"zh-TW":["市場經濟"],"en":["an economic system based on supply, demand, and private ownership"]}', NULL, 'free market economy / market economy principles', '[{"en":"In a market economy, prices are determined by supply and demand.","zh-TW":"在市場經濟中，價格由供求關係決定。"},{"en":"The country transitioned to a market economy in the 1990s.","zh-TW":"該國在1990年代轉型為市場經濟。"}]', NULL, NULL, 5, 4138, NULL),
(4139, 'market entry', '/ˈmɑːrkɪt ˈentri/', 'noun', '{"zh-TW":["進入市場；市場進入"],"en":["the process of entering a new market with a product or service"]}', NULL, 'market entry strategy / market entry barriers / facilitate market entry', '[{"en":"The market entry strategy focused on partnerships with local distributors.","zh-TW":"市場進入策略側重於與當地分銷商的合作關係。"},{"en":"High capital requirements create barriers to market entry.","zh-TW":"高資本要求造成了市場進入壁壘。"}]', NULL, NULL, 4, 4139, NULL),
(4140, 'market entry barrier', '/ˈmɑːrkɪt ˈentri ˈbæriər/', 'noun', '{"zh-TW":["市場進入壁壘"],"en":["obstacles that prevent new companies from easily entering a market"]}', NULL, 'overcome market entry barriers / high market entry barriers', '[{"en":"Regulatory requirements are a significant market entry barrier in healthcare.","zh-TW":"監管要求是醫療保健領域的重大市場進入壁壘。"},{"en":"High capital requirements create market entry barriers for new competitors.","zh-TW":"高資本要求為新競爭者創造了市場進入壁壘。"}]', NULL, NULL, 5, 4140, NULL),
(4141, 'market exit', '/ˈmɑːrkɪt ˈeksɪt/', 'noun', '{"zh-TW":["退出市場"],"en":["the process of withdrawing a product or company from a market"]}', NULL, 'market exit strategy / execute a market exit', '[{"en":"The company planned an orderly market exit from underperforming regions.","zh-TW":"公司計劃從表現不佳的地區有序退出市場。"},{"en":"Market exit can release capital for more profitable ventures.","zh-TW":"退出市場可以為更有利可圖的企業釋放資金。"}]', NULL, NULL, 4, 4141, NULL),
(4142, 'market failure', '/ˈmɑːrkɪt ˈfeɪljər/', 'noun', '{"zh-TW":["市場失靈"],"en":["a situation where markets fail to allocate resources efficiently"]}', NULL, 'identify market failure / correct market failure', '[{"en":"Negative externalities are a classic example of market failure.","zh-TW":"負外部性是市場失靈的典型例子。"},{"en":"Government intervention aims to correct market failure in public goods.","zh-TW":"政府幹預旨在糾正公共物品方面的市場失靈。"}]', NULL, NULL, 5, 4142, NULL),
(4143, 'market forces', '/ˈmɑːrkɪt fɔːrsɪz/', 'noun', '{"zh-TW":["市場力量；市場機制"],"en":["natural economic pressures of supply and demand affecting prices"]}', NULL, 'respond to market forces / driven by market forces', '[{"en":"Prices are set by market forces rather than government intervention.","zh-TW":"價格由市場力量而非政府干預決定。"},{"en":"Market forces pushed down the price of smartphones significantly.","zh-TW":"市場力量顯著壓低了智慧型手機的價格。"}]', NULL, NULL, 5, 4143, NULL),
(4144, 'market forecast', '/''mɑːrkɪt ˌfɔːrkɑːst/', 'noun', '{"zh-TW":["市場預測"],"en":["a prediction of how a market will develop, typically based on trends and analysis"]}', NULL, 'prepare a market forecast / market forecast accuracy / update the market forecast', '[{"en":"Analysts revised their market forecast upward following stronger-than-expected economic data.","zh-TW":"分析師在強於預期的經濟數據公布後上調了市場預測。"},{"en":"A reliable market forecast is essential for making sound strategic investment decisions.","zh-TW":"可靠的市場預測對於做出健全的戰略投資決策至關重要。"}]', '{"verb":"forecast","noun2":"forecaster"}', NULL, 5, 4144, NULL),
(4145, 'market intelligence', '/ˈmɑːrkɪt ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["市場情報"],"en":["information gathered about a market, its customers, and competitors"]}', NULL, 'gather market intelligence / market intelligence report', '[{"en":"Market intelligence revealed a growing demand for sustainable packaging.","zh-TW":"市場情報揭示了對可持續包裝日益增長的需求。"},{"en":"Sales teams regularly gather market intelligence from client interactions.","zh-TW":"銷售團隊定期從客戶互動中收集市場情報。"}]', NULL, NULL, 5, 4145, NULL),
(4146, 'market leader', '/ˈmɑːrkɪt ˈliːdər/', 'noun', '{"zh-TW":["市場領導者；市場龍頭"],"en":["the company with the largest share of a particular market"]}', NULL, 'become a market leader / defend market leader position', '[{"en":"The brand is the undisputed market leader in the region.","zh-TW":"該品牌是該地區無可爭議的市場領導者。"},{"en":"Being a market leader carries pricing power and brand recognition benefits.","zh-TW":"成為市場領導者帶來了定價能力和品牌認知優勢。"}]', NULL, NULL, 5, 4146, NULL),
(4147, 'market liquidity', '/ˈmɑːrkɪt lɪˈkwɪdɪti/', 'noun', '{"zh-TW":["市場流動性"],"en":["the ease with which securities can be bought and sold without affecting their price"]}', NULL, 'monitor market liquidity / improve market liquidity', '[{"en":"High market liquidity allows investors to exit positions with minimal price impact.","zh-TW":"高市場流動性允許投資者以最小的價格影響退出倉位。"},{"en":"Market liquidity dried up during the financial crisis of 2008.","zh-TW":"在2008年金融危機期間，市場流動性枯竭了。"}]', NULL, NULL, 5, 4147, NULL),
(4148, 'market maker', '/ˈmɑːrkɪt ˈmeɪkər/', 'noun', '{"zh-TW":["做市商"],"en":["a firm that actively quotes buy and sell prices to provide market liquidity"]}', NULL, 'role of market maker / market maker spread', '[{"en":"Market makers ensure continuous trading by quoting bid and ask prices.","zh-TW":"做市商通過報出買入價和賣出價確保持續交易。"},{"en":"The spread charged by a market maker is the primary source of revenue.","zh-TW":"做市商收取的差價是其主要收入來源。"}]', NULL, NULL, 4, 4148, NULL),
(4149, 'market outlook', '/ˈmɑːrkɪt ˈaʊtlʊk/', 'noun', '{"zh-TW":["市場前景"],"en":["a forecast or assessment of expected market conditions over a period"]}', NULL, 'assess market outlook / positive market outlook', '[{"en":"The analyst presented a positive market outlook for consumer goods.","zh-TW":"分析師對消費品提出了積極的市場前景。"},{"en":"A weak market outlook may delay investment decisions.","zh-TW":"疲軟的市場前景可能會推遲投資決策。"}]', NULL, NULL, 5, 4149, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4150, 'market penetration', '/ˈmɑːrkɪt ˌpɛnɪˈtreɪʃən/', 'noun', '{"zh-TW":["市場滲透"],"en":["the extent to which a product is known and used in a market"]}', NULL, 'increase market penetration / market penetration strategy', '[{"en":"The company''s goal is to increase market penetration in Asia.","zh-TW":"公司的目標是提高在亞洲的市場滲透率。"},{"en":"Competitive pricing is a common market penetration strategy.","zh-TW":"競爭性定價是常見的市場滲透策略。"}]', NULL, NULL, 5, 4150, NULL),
(4151, 'market position', '/ˈmɑːrkɪt pəˈzɪʃən/', 'noun', '{"zh-TW":["市場地位；市場定位"],"en":["a company standing in a market relative to competitors"]}', NULL, 'strengthen market position / defend market position', '[{"en":"The company strengthened its market position through innovation.","zh-TW":"公司通過創新強化了市場地位。"},{"en":"A strong market position provides pricing power and customer loyalty.","zh-TW":"強大的市場地位提供了定價能力和客戶忠誠度。"}]', NULL, NULL, 5, 4151, NULL),
(4152, 'market positioning', '/ˈmɑːrkɪt pəˈzɪʃənɪŋ/', 'noun', '{"zh-TW":["市場定位"],"en":["how a company or product is perceived relative to competitors in the market"]}', NULL, 'define market positioning / refine market positioning', '[{"en":"Clear market positioning as a premium brand justified higher prices.","zh-TW":"作為高端品牌的清晰市場定位證明了較高價格的合理性。"},{"en":"Market positioning guides all branding and communication decisions.","zh-TW":"市場定位指導了所有品牌和傳播決策。"}]', NULL, NULL, 5, 4152, NULL),
(4153, 'market research', '/ˈmɑːrkɪt rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["市場研究"],"en":["the process of gathering information about consumers and market conditions"]}', NULL, 'conduct market research / market research report / qualitative market research', '[{"en":"Market research revealed strong demand for the new product.","zh-TW":"市場研究顯示新產品有強烈需求。"},{"en":"The company invested heavily in market research before the launch.","zh-TW":"公司在上市前在市場研究上投入了大量資金。"}]', '{"verb":"research the market","noun":"market researcher"}', NULL, 5, 4153, NULL),
(4154, 'market research report', '/ˈmɑːrkɪt rɪˈsɜːrtʃ rɪˈpɔːrt/', 'noun', '{"zh-TW":["市場調研報告"],"en":["a document summarizing findings from research on a market or consumer group"]}', NULL, 'commission a market research report / market research report findings', '[{"en":"The market research report showed strong demand for eco-friendly packaging.","zh-TW":"市場調研報告顯示對環保包裝的需求強勁。"},{"en":"Market research reports inform product development and marketing strategy.","zh-TW":"市場調研報告為產品開發和行銷策略提供了信息。"}]', NULL, NULL, 5, 4154, NULL),
(4155, 'market risk', '/ˈmɑːrkɪt rɪsk/', 'noun', '{"zh-TW":["市場風險"],"en":["the risk of losses due to adverse movements in market prices or rates"]}', NULL, 'manage market risk / market risk assessment', '[{"en":"The portfolio manager hedged market risk using derivative instruments.","zh-TW":"投資組合管理人使用衍生品工具對沖市場風險。"},{"en":"Market risk includes equity risk, interest rate risk, and currency risk.","zh-TW":"市場風險包括股票風險、利率風險和貨幣風險。"}]', '{"synonym":"systematic risk"}', NULL, 4, 4155, NULL),
(4156, 'market saturation', '/ˈmɑːrkɪt ˌsætʃəˈreɪʃən/', 'noun', '{"zh-TW":["市場飽和"],"en":["when a product or service has been sold to most potential customers"]}', NULL, 'face market saturation / overcome market saturation', '[{"en":"Market saturation forced the company to look for new customer segments.","zh-TW":"市場飽和迫使公司尋找新的客戶細分。"},{"en":"Innovation can reverse market saturation by creating new demand.","zh-TW":"創新可以通過創造新需求逆轉市場飽和。"}]', NULL, NULL, 5, 4156, NULL),
(4157, 'market segment', '/ˈmɑːrkɪt ˈseɡmənt/', 'noun', '{"zh-TW":["市場區隔；細分市場"],"en":["a subgroup of consumers with similar needs or characteristics"]}', NULL, 'target a market segment / market segment analysis', '[{"en":"The company focused on the premium market segment for its new product.","zh-TW":"公司將新產品聚焦在高端市場區隔。"},{"en":"Identifying the right market segment improves marketing ROI.","zh-TW":"識別正確的市場區隔改善了行銷投資回報率。"}]', NULL, NULL, 5, 4157, NULL),
(4158, 'market segmentation', '/ˈmɑːrkɪt ˌseɡmənˈteɪʃən/', 'noun', '{"zh-TW":["市場細分"],"en":["dividing a market into distinct groups with similar needs or characteristics"]}', NULL, 'demographic segmentation / psychographic segmentation / target market segmentation', '[{"en":"Market segmentation helped the company tailor its messaging.","zh-TW":"市場細分幫助公司量身訂製其訊息傳遞。"},{"en":"Geographic market segmentation drives localized marketing strategies.","zh-TW":"地理市場細分推動了本地化行銷策略。"}]', '{"verb":"segment","adjective":"segmented"}', NULL, 5, 4158, NULL),
(4159, 'market share', '/ˈmɑːrkɪt ʃeər/', 'noun', '{"zh-TW":["市場份額"],"en":["the portion of a market controlled by a particular company or product"]}', NULL, 'increase market share / lose market share / dominant market share', '[{"en":"The company gained market share by reducing prices.","zh-TW":"公司通過降低價格獲得了市場份額。"},{"en":"Their market share rose to 35% following the acquisition.","zh-TW":"收購後，他們的市場份額上升至35%。"}]', '{"verb":"capture market share"}', NULL, 4, 4159, NULL),
(4160, 'market share analysis', '/ˈmɑːrkɪt ʃeər əˈnæləsɪs/', 'noun', '{"zh-TW":["市場份額分析"],"en":["assessing a company percentage of total market sales"]}', NULL, 'conduct a market share analysis / market share analysis report', '[{"en":"The market share analysis showed a 5% gain over competitors.","zh-TW":"市場份額分析顯示比競爭對手增加了5%。"},{"en":"Annual market share analysis tracks competitive trends over time.","zh-TW":"年度市場份額分析追蹤競爭趨勢。"}]', NULL, NULL, 5, 4160, NULL),
(4161, 'market share growth', '/ˈmɑːrkɪt ʃeər ɡroʊθ/', 'noun', '{"zh-TW":["市場份額增長"],"en":["an increase in the percentage of total market sales captured by a company"]}', NULL, 'achieve market share growth / market share growth strategy', '[{"en":"Aggressive pricing contributed to significant market share growth.","zh-TW":"激進的定價促成了顯著的市場份額增長。"},{"en":"Market share growth is a key metric for assessing competitive success.","zh-TW":"市場份額增長是評估競爭成功的關鍵指標。"}]', NULL, NULL, 5, 4161, NULL),
(4162, 'market trend', '/ˈmɑːrkɪt trend/', 'noun', '{"zh-TW":["市場趨勢"],"en":["the general direction in which a market is moving over time"]}', NULL, 'identify market trends / follow market trends / emerging market trends', '[{"en":"The market trend toward sustainability is reshaping consumer preferences.","zh-TW":"向永續性轉變的市場趨勢正在重塑消費者偏好。"},{"en":"Analysts track market trends to forecast future demand.","zh-TW":"分析師追蹤市場趨勢以預測未來需求。"}]', '{"plural":"market trends"}', NULL, 4, 4162, NULL),
(4163, 'market valuation', '/ˈmɑːrkɪt ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["市值估算；市場估值"],"en":["an estimate of a company worth based on current market data"]}', NULL, 'assess market valuation / market valuation method', '[{"en":"The company market valuation doubled after the product launch.","zh-TW":"產品發佈後，公司市值估算翻了一倍。"},{"en":"Market valuation is used in M&A negotiations to set deal pricing.","zh-TW":"市場估值用於併購談判以設定交易定價。"}]', NULL, NULL, 5, 4163, NULL),
(4164, 'market value', '/''mɑːrkɪt ˌvæljuː/', 'noun', '{"zh-TW":["市場價值；市場估值"],"en":["the estimated amount for which a property should be bought or sold on the open market"]}', NULL, 'assess market value / determine market value / below market value', '[{"en":"The house sold for significantly above its assessed market value.","zh-TW":"房子的售價遠高於其評估的市場價值。"},{"en":"Properties near good schools typically have a higher market value.","zh-TW":"靠近好學校的房產通常具有更高的市場價值。"}]', NULL, NULL, 4, 4164, NULL),
(4165, 'marketing automation', '/ˈmɑːrkɪtɪŋ ˌɔːtəˈmeɪʃən/', 'noun', '{"zh-TW":["行銷自動化"],"en":["using software to automate repetitive marketing tasks"]}', NULL, 'marketing automation platform / implement marketing automation', '[{"en":"Marketing automation streamlines lead nurturing campaigns.","zh-TW":"行銷自動化簡化了潛在客戶培育活動。"},{"en":"The team uses marketing automation to send personalized emails at scale.","zh-TW":"團隊使用行銷自動化大規模發送個人化電子郵件。"}]', '{"verb":"automate marketing"}', NULL, 5, 4165, NULL),
(4166, 'marketing mix', '/ˈmɑːrkɪtɪŋ mɪks/', 'noun', '{"zh-TW":["行銷組合"],"en":["the combination of factors used to market a product"]}', NULL, 'develop a marketing mix / marketing mix strategy', '[{"en":"The classic marketing mix includes product, price, place, and promotion.","zh-TW":"傳統的行銷組合包括產品、價格、通路和促銷。"},{"en":"An effective marketing mix drives both sales and brand awareness.","zh-TW":"有效的行銷組合同時推動了銷售和品牌知名度。"}]', NULL, NULL, 5, 4166, NULL),
(4167, 'markup', '/ˈmɑːrkʌp/', 'noun', '{"zh-TW":["加價；標記"],"en":["the amount added to cost price for profit"]}', NULL, 'price markup / markup percentage', '[{"en":"Retailers typically apply a 50% markup on wholesale prices.","zh-TW":"零售商通常在批發價上加價50%。"},{"en":"The markup on luxury goods is significantly higher.","zh-TW":"奢侈品的加價幅度明顯更高。"}]', '{"noun":"markup","verb":"mark up"}', NULL, 2, 4167, NULL),
(4168, 'marry', '/ˈmæri/', 'verb', '{"zh-TW":["結婚"],"en":["to become the spouse of someone"]}', NULL, 'get married / married life', '[{"en":"They got married last summer.","zh-TW":"他們去年夏天結婚了。"},{"en":"She is married with two children.","zh-TW":"她已婚並育有兩個孩子。"}]', '{"verb":"marry","noun":"marriage","adjective":"married","adjective2":"unmarried"}', NULL, 2, 4168, NULL),
(4169, 'massive', '/ˈmæsɪv/', 'adjective', '{"zh-TW":["大量的；巨大的"],"en":["extremely large or serious"]}', NULL, 'massive investment/growth/change', '[{"en":"The project requires a massive investment.","zh-TW":"該項目需要大量投資。"},{"en":"There has been massive growth in online shopping.","zh-TW":"網上購物出現了大幅增長。"}]', '{"noun":"mass","adjective":"massive","adverb":"massively"}', NULL, 3, 4169, NULL),
(4170, 'master', '/ˈmæstər/', 'noun, verb, adjective', '{"zh-TW":["【主要意義-名詞】主人；碩士","【次要意義-動詞】精通；掌握（技能）","【次要意義-形容詞】主要的；最終版本的（文件）","【次要意義-名詞】原版；母片"],"en":["[primary - noun] a person with great skill or authority","[secondary - verb] to become skilled at something through practice","[secondary - adjective] relating to the main or original version of something","[secondary - noun] an original recording or document"]}', NULL, 'master plan / master copy / master a skill / master key', '[{"en":"It takes years of practice to master the art of negotiation.","zh-TW":"掌握談判藝術需要多年的練習。"},{"en":"Please send the master copy of the contract to the legal department.","zh-TW":"請將合約的原版副本發送至法律部門。"},{"en":"The company revealed its master plan for expansion into Southeast Asia.","zh-TW":"公司公布了其向東南亞擴張的總體計劃。"}]', '{"noun":"masterpiece, mastery","adjective":"masterful"}', '動詞 master = 「精通/掌握」是高頻用法；master plan（總體計劃）、master copy（原版）、master key（萬能鑰匙）均是 TOEIC 商業和管理文章常見搭配。', 2, 4170, NULL),
(4171, 'master agreement', '/ˈmɑːstər əˈɡriːmənt/', 'noun', '{"zh-TW":["主協議；框架協議"],"en":["an overarching contract governing a business relationship with multiple transactions"]}', NULL, 'sign a master agreement / operate under a master agreement', '[{"en":"The two parties signed a master agreement to govern all future transactions.","zh-TW":"雙方簽署了管理所有未來交易的主協議。"},{"en":"A master agreement simplifies individual transaction documentation.","zh-TW":"主協議簡化了個別交易的文件。"}]', NULL, NULL, 5, 4171, NULL),
(4172, 'master budget', '/ˈmɑːstər ˈbʌdʒɪt/', 'noun', '{"zh-TW":["主預算"],"en":["the comprehensive annual plan integrating all departmental budgets"]}', NULL, 'prepare the master budget / approve the master budget', '[{"en":"The master budget was finalized after each department submitted its budget.","zh-TW":"各部門提交預算後，主預算得以定稿。"},{"en":"The master budget serves as the financial roadmap for the entire year.","zh-TW":"主預算為全年提供了財務路線圖。"}]', NULL, NULL, 5, 4172, NULL),
(4173, 'master franchise', '/ˈmɑːstər ˈfrænʃaɪz/', 'noun', '{"zh-TW":["總特許經營權"],"en":["an arrangement granting a franchisee the right to sub-franchise in a territory"]}', NULL, 'grant a master franchise / master franchise agreement', '[{"en":"The company awarded a master franchise for the Middle East region.","zh-TW":"公司授予了中東地區的總特許經營權。"},{"en":"Master franchise holders are responsible for supporting sub-franchisees.","zh-TW":"總特許經營權持有人負責支援子加盟商。"}]', NULL, NULL, 5, 4173, NULL),
(4174, 'master of ceremonies', '/ˈmɑːstər əv ˈsɛrɪməniːz/', 'noun', '{"zh-TW":["司儀；主持人"],"en":["a person who oversees a formal event or ceremony"]}', NULL, 'act as master of ceremonies / experienced master of ceremonies', '[{"en":"The master of ceremonies welcomed the guests and introduced speakers.","zh-TW":"司儀歡迎了賓客並介紹了演講者。"},{"en":"She was chosen as master of ceremonies for the awards dinner.","zh-TW":"她被選為頒獎晚宴的司儀。"}]', '{"abbreviation":"MC"}', NULL, 5, 4174, NULL),
(4175, 'master service agreement', '/ˈmɑːstər ˈsɜːrvɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["主服務協議"],"en":["a contract establishing the general terms governing a business relationship"]}', NULL, 'sign a master service agreement / master service agreement template', '[{"en":"The master service agreement covered all future projects between the two firms.","zh-TW":"主服務協議涵蓋了兩家公司之間所有未來的項目。"},{"en":"Individual project scopes are added as appendices to the master service agreement.","zh-TW":"個別項目範圍作為附件添加到主服務協議中。"}]', '{"abbreviation":"MSA"}', NULL, 5, 4175, NULL),
(4176, 'masterpiece', '/ˈmæstərpiːs/', 'noun', '{"zh-TW":["傑作"],"en":["a work of outstanding artistry or skill"]}', '{"root":{"text":"master","meaning":"master (大師)"},"suffix":{"text":"piece","meaning":"piece/work (作品)"},"logic":"大師的作品，即「傑作」。"}', 'literary masterpiece / create a masterpiece', '[{"en":"The Mona Lisa is considered a masterpiece.","zh-TW":"蒙娜麗莎被視為傑作。"},{"en":"This novel is his greatest masterpiece.","zh-TW":"這部小說是他最偉大的傑作。"}]', NULL, NULL, 4, 4176, NULL),
(4177, 'match', '/mætʃ/', 'verb', '{"zh-TW":["匹配；比賽"],"en":["to be equal to","a contest"]}', NULL, 'perfect match / match up', '[{"en":"We need a candidate who matches the job requirements.","zh-TW":"我們需要一位符合工作要求的候選人。"},{"en":"Her skills are a perfect match for the role.","zh-TW":"她的技能與這個職位完美匹配。"}]', '{"verb":"match","noun":"match","adjective":"matching"}', NULL, 2, 4177, NULL),
(4178, 'material', '/məˈtɪriəl/', 'noun, adjective', '{"zh-TW":["材料；物質","重要的；物質的"],"en":["the substance things are made from","significant; relating to physical things"]}', NULL, 'raw material / reading material / material change', '[{"en":"The cost of raw materials has risen sharply.","zh-TW":"原材料成本大幅上升。"},{"en":"There has been no material change in our financial position.","zh-TW":"我們的財務狀況沒有重大變化。"}]', '{"noun":"material, materialism","adjective":"material","adverb":"materially"}', NULL, 3, 4178, 391),
(4179, 'material breach', '/məˈtɪəriəl briːtʃ/', 'noun', '{"zh-TW":["實質性違約"],"en":["a serious violation of a contract that undermines its purpose"]}', NULL, 'commit a material breach / remedy a material breach', '[{"en":"A material breach entitles the other party to terminate the contract.","zh-TW":"實質性違約賦予另一方終止合約的權利。"},{"en":"The delayed payment was deemed a material breach.","zh-TW":"延遲付款被認定為實質性違約。"}]', NULL, NULL, 5, 4179, NULL),
(4180, 'material cost', '/məˈtɪəriəl kɒst/', 'noun', '{"zh-TW":["材料成本"],"en":["the cost of raw materials or components used in production"]}', NULL, 'manage material costs / reduce material costs', '[{"en":"Rising material costs were offset by efficiency gains.","zh-TW":"上漲的材料成本被效率提升所抵消。"},{"en":"Material costs represent 40% of the total production cost.","zh-TW":"材料成本占總生產成本的40%。"}]', NULL, NULL, 5, 4180, NULL),
(4181, 'material information', '/məˈtɪəriəl ˌɪnfəˈmeɪʃən/', 'noun', '{"zh-TW":["重大信息；重要信息"],"en":["information that could reasonably influence an investor''s decision"]}', NULL, 'disclose material information / material information obligation', '[{"en":"Listed companies must disclose material information without delay.","zh-TW":"上市公司必須毫不延遲地披露重大信息。"},{"en":"Withholding material information from investors may violate securities law.","zh-TW":"對投資者隱瞞重大信息可能違反證券法。"}]', NULL, NULL, 5, 4181, NULL),
(4182, 'materiality', '/məˌtɪəriˈæləti/', 'noun', '{"zh-TW":["重大性；重要性"],"en":["the significance of information in relation to financial decisions"]}', NULL, 'assess materiality / materiality threshold', '[{"en":"The auditor determined the materiality threshold at 1% of revenue.","zh-TW":"審計師將重大性門檻確定為收入的1%。"},{"en":"Materiality determines what information must be disclosed in accounts.","zh-TW":"重大性決定了帳目中必須披露的資訊。"}]', '{"adjective":"material","adverb":"materially"}', NULL, 4, 4182, NULL),
(4183, 'materiality threshold', '/məˌtɪəriˈælɪti ˈθreʃhoʊld/', 'noun', '{"zh-TW":["重要性門檻"],"en":["the level at which an omission or misstatement would influence a financial decision"]}', NULL, 'set a materiality threshold / below the materiality threshold', '[{"en":"The auditor set a materiality threshold of 5% of pre-tax income.","zh-TW":"審計師設定了稅前收入5%的重要性門檻。"},{"en":"Errors below the materiality threshold do not require correction.","zh-TW":"低於重要性門檻的錯誤不需要更正。"}]', NULL, NULL, 5, 4183, NULL),
(4184, 'maternity leave', '/məˈtɜːrnɪti liːv/', 'noun', '{"zh-TW":["產假"],"en":["paid or unpaid time off granted to mothers before and after childbirth"]}', NULL, 'take maternity leave / paid maternity leave / return from maternity leave', '[{"en":"She took 12 weeks of paid maternity leave after her baby was born.","zh-TW":"孩子出生後，她休了12週的有薪產假。"},{"en":"The company extended maternity leave to 26 weeks.","zh-TW":"公司將產假延長至26週。"}]', NULL, NULL, 5, 4184, NULL),
(4185, 'matrix', '/ˈmeɪtrɪks/', 'noun', '{"zh-TW":["矩陣；基質"],"en":["a grid arrangement; an environment in which something develops"]}', NULL, 'decision matrix / risk matrix / matrix organization', '[{"en":"We used a decision matrix to evaluate options.","zh-TW":"我們使用決策矩陣來評估選項。"},{"en":"The company operates under a matrix structure.","zh-TW":"公司以矩陣結構運作。"}]', '{"noun":"matrix"}', NULL, 2, 4185, NULL),
(4186, 'matrix management', '/ˈmeɪtrɪks ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["矩陣式管理"],"en":["a management structure where employees report to multiple managers"]}', NULL, 'work in a matrix management structure / benefits of matrix management', '[{"en":"Matrix management enables flexible resource sharing across projects.","zh-TW":"矩陣式管理實現了跨項目的靈活資源共享。"},{"en":"Clear communication is essential in a matrix management environment.","zh-TW":"在矩陣式管理環境中，清晰的溝通至關重要。"}]', NULL, NULL, 5, 4186, NULL),
(4187, 'matrix organization', '/ˈmeɪtrɪks ˌɔːrɡənəˈzeɪʃən/', 'noun', '{"zh-TW":["矩陣式組織"],"en":["an organizational structure with dual reporting relationships"]}', NULL, 'matrix organization structure / work in a matrix organization', '[{"en":"A matrix organization allows employees to report to both functional and project managers.","zh-TW":"矩陣式組織允許員工同時向職能和項目經理匯報。"},{"en":"Navigating a matrix organization requires strong communication skills.","zh-TW":"在矩陣式組織中運作需要強大的溝通技巧。"}]', NULL, NULL, 5, 4187, NULL),
(4188, 'matter', '/ˈmætər/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】事情；物質；問題","【次要意義-動詞】重要；有關係；有影響"],"en":["[primary - noun] a subject or situation; physical substance","[secondary - verb] to be important or significant"]}', NULL, 'it matters / matter of fact / no matter what / as a matter of course', '[{"en":"It matters a great deal how we communicate with our clients.","zh-TW":"我們與客戶的溝通方式非常重要。"},{"en":"As a matter of policy, all complaints must be addressed within 48 hours.","zh-TW":"按照慣例，所有投訴必須在48小時內處理。"},{"en":"The timing of the announcement matters more than its content.","zh-TW":"公告的時機比其內容更為重要。"}]', '{"adjective":"immaterial"}', '動詞 matter = 「重要/有意義」，常見句型 it matters that.../ what matters is...，片語 as a matter of + noun（作為……事項）是 TOEIC 商業文章常見正式表達。', 2, 4188, NULL),
(4189, 'mature', '/məˈtʃʊr/', 'adjective, verb', '{"zh-TW":["成熟的","到期；成熟"],"en":["fully developed; sensible","to reach full development; (of investments) to reach payment date"]}', NULL, 'mature market/industry / bond matures', '[{"en":"The market has matured and growth is slowing.","zh-TW":"市場已經成熟，增長正在放緩。"},{"en":"The bond matures in five years.","zh-TW":"債券五年後到期。"}]', '{"noun":"maturity","adjective":"mature","verb":"mature"}', NULL, 2, 4189, NULL),
(4190, 'mature student', '/''mətʃʊər ˌstjuːdənt/', 'noun', '{"zh-TW":["成熟學生；成年學生"],"en":["a student who is older than the typical university entry age, usually 21 or over"]}', NULL, 'support mature students / mature student experience / apply as a mature student', '[{"en":"As a mature student, she brought valuable work experience to the classroom.","zh-TW":"作為成熟學生，她為課堂帶來了寶貴的工作經驗。"},{"en":"Mature students often perform exceptionally well due to their high motivation.","zh-TW":"成熟學生往往因高度積極性而表現出色。"}]', NULL, NULL, 5, 4190, NULL),
(4191, 'maturity', '/məˈtʃʊərɪti/', 'noun', '{"zh-TW":["到期日；成熟"],"en":["the date on which a financial obligation becomes due; the state of being fully developed"]}', NULL, 'bond maturity / at maturity / maturity date', '[{"en":"Bondholders receive the principal at the bond''s maturity date.","zh-TW":"債券持有人在債券到期日收回本金。"},{"en":"The project reached maturity after years of development and investment.","zh-TW":"這個項目在多年的發展和投資後進入了成熟階段。"}]', '{"adjective":"mature","verb":"mature"}', NULL, 3, 4191, NULL),
(4192, 'maturity date', '/məˈtjʊərɪti deɪt/', 'noun', '{"zh-TW":["到期日；期滿日"],"en":["the date when a bond or loan becomes due and payable in full"]}', NULL, 'bond maturity date / loan maturity date', '[{"en":"The bond reaches its maturity date on December 31.","zh-TW":"債券在12月31日到達到期日。"},{"en":"The company planned to refinance the debt before its maturity date.","zh-TW":"公司計劃在到期日前對債務進行再融資。"}]', NULL, NULL, 5, 4192, NULL),
(4193, 'maturity mismatch', '/məˈtʃʊərɪti ˈmɪsmætʃ/', 'noun', '{"zh-TW":["期限錯配"],"en":["the difference between the maturities of a bank''s assets and liabilities"]}', NULL, 'address maturity mismatch / maturity mismatch risk / solve the maturity mismatch', '[{"en":"A maturity mismatch between short-term deposits and long-term loans can cause bank runs.","zh-TW":"短期存款和長期貸款之間的期限錯配可能導致銀行擠兌。"},{"en":"Regulators monitor maturity mismatch to ensure banks can meet withdrawal demands.","zh-TW":"監管機構監控期限錯配，以確保銀行能夠滿足提款需求。"}]', NULL, NULL, 5, 4193, NULL),
(4194, 'maximization of profit', '/ˌmæksɪmaɪˈzeɪʃən əv ˈprɒfɪt/', 'noun', '{"zh-TW":["利潤最大化"],"en":["the goal of a firm to achieve the highest possible profit"]}', NULL, 'focus on maximization of profit / profit maximization objective', '[{"en":"Shareholders expect management to pursue maximization of profit.","zh-TW":"股東期望管理層追求利潤最大化。"},{"en":"Maximization of profit must be balanced against long-term sustainability.","zh-TW":"利潤最大化必須與長期可持續性相平衡。"}]', NULL, NULL, 5, 4194, NULL),
(4195, 'maximize', '/ˈmæksɪmaɪz/', 'verb', '{"zh-TW":["最大化；充分利用"],"en":["to make as large or great as possible"]}', NULL, 'maximize profit/efficiency/potential', '[{"en":"We aim to maximize shareholder value.","zh-TW":"我們的目標是最大化股東價值。"},{"en":"How can we maximize the use of our resources?","zh-TW":"我們如何才能最大限度地利用資源？"}]', '{"noun":"maximum","verb":"maximize","adjective":"maximum"}', NULL, 3, 4195, 153),
(4196, 'maximum', 'ˈmæksɪməm', 'noun', '{"zh-TW":["最大值；最大量","極限"],"en":["the greatest possible amount","an upper limit"]}', NULL, 'maximum capacity/at maximum', '[{"en":"We are at maximum production capacity.","zh-TW":"我們處於最大生產能力。"}]', '{"adjective":"maximum","adverb":"maximally"}', NULL, 3, 4196, 392),
(4197, 'maître d''', '/ˌmeɪtrə ˈdiː/', 'noun', '{"zh-TW":["餐廳領班；接待長"],"en":["the head waiter of a restaurant"]}', NULL, 'ask the maître d'' / experienced maître d''', '[{"en":"The maître d'' escorted us to our reserved table.","zh-TW":"領班帶領我們到預訂的桌位。"},{"en":"The maître d'' ensured every guest was well taken care of.","zh-TW":"領班確保每位賓客都得到妥善照顧。"}]', NULL, NULL, 3, 4197, NULL),
(4198, 'meager', '/''miːɡər/', 'adjective', '{"zh-TW":["微薄的；不足的"],"en":["lacking in quantity or quality; insufficient"]}', NULL, 'meager salary / meager resources / meager return', '[{"en":"The startup survived on meager funding in its first year of operation.","zh-TW":"這家新創公司在第一年運營中靠著微薄的資金生存下來。"},{"en":"Despite meager resources, the team produced an impressive result.","zh-TW":"儘管資源匱乏，團隊仍產生了令人印象深刻的成果。"}]', '{"adverb":"meagerly","noun":"meagerness"}', NULL, 2, 4198, NULL),
(4199, 'meal', '/miːl/', 'noun', '{"zh-TW":["一餐；膳食"],"en":["food eaten at a particular time"]}', NULL, 'meal allowance / business meal', '[{"en":"Employees receive a meal allowance.","zh-TW":"員工有餐費補貼。"},{"en":"Business meals are tax-deductible.","zh-TW":"商務餐費可以扣稅。"}]', '{"noun":"meal"}', NULL, 1, 4199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(4200, 'meal prep', '/''miːl prep/', 'noun', '{"zh-TW":["備餐；預先備料"],"en":["the practice of preparing meals or components of meals in advance to save time during the week"]}', NULL, 'weekly meal prep / meal prep routine / batch meal prep', '[{"en":"She dedicates Sunday afternoons to meal prep for the entire week.","zh-TW":"她每個星期天下午都用來為整個星期備餐。"},{"en":"Meal prep helps people eat healthier by reducing the temptation of fast food.","zh-TW":"備餐通過減少快餐的誘惑幫助人們吃得更健康。"}]', NULL, NULL, 3, 4200, NULL),
(4201, 'mean', '/miːn/', 'verb', '{"zh-TW":["【主要意義-動詞】意味著；表示","【次要意義-形容詞】低賤的；吝嗇的；惡劣的；殘忍的","【次要意義-名詞（數學）】平均數；中間值","【次要意義-形容詞】出色的；高超的（非正式）"],"en":["[primary - verb] to signify or indicate something","[secondary - adjective] unkind or cruel; unwilling to give","[secondary - noun] a middle point or average value","[secondary - adjective] (informal) excellent or skillful"]}', NULL, 'mean business / by no means / means of communication / golden mean', '[{"en":"The new director means business and has already implemented major changes.","zh-TW":"新主任是認真的，已經實施了重大改革。"},{"en":"This is by no means a simple task and requires expert guidance.","zh-TW":"這絕非一項簡單的任務，需要專家指導。"},{"en":"The mean salary in the sector increased by 5 percent last year.","zh-TW":"該行業的平均薪資去年增加了5%。"}]', '{"noun":"meaning, means","adjective":"meaningful"}', 'mean business（認真對待）、by no means（絕不）、means（方法/手段）是 TOEIC 高頻表達；形容詞 mean = 「吝嗇的/惡劣的」，名詞 mean = 「平均值」均是次要意義陷阱。', 1, 4201, NULL),
(4202, 'mean reversion', '/miːn rɪˈvɜːrʃən/', 'noun', '{"zh-TW":["均值回歸"],"en":["the tendency of financial metrics to return toward their long-run average"]}', NULL, 'mean reversion strategy / test for mean reversion / evidence of mean reversion', '[{"en":"Mean reversion suggests that extreme performance is unlikely to persist.","zh-TW":"均值回歸表明極端業績不可能持續。"},{"en":"Value investors rely on mean reversion to justify buying undervalued assets.","zh-TW":"價值投資者依靠均值回歸來支持購買被低估資產的決策。"}]', NULL, NULL, 5, 4202, NULL),
(4203, 'meaning', 'ˈmiːnɪŋ', 'noun', '{"zh-TW":["意義；含義","目的"],"en":["what something represents","the importance of something"]}', NULL, 'hidden meaning/double meaning', '[{"en":"What is the meaning of this abbreviation?","zh-TW":"這個縮寫的含義是什麼？"}]', '{"verb":"mean","adjective":"meaningful, meaningless","adverb":"meaningfully"}', NULL, 3, 4203, NULL),
(4204, 'means-tested', '/miːnz test/', 'adjective', '{"zh-TW":["依收入審查的"],"en":["eligibility for which depends on the claimant''s income and assets"]}', NULL, 'means-tested benefit / means-tested welfare / means-tested program', '[{"en":"Means-tested benefits ensure that government aid reaches those most in need.","zh-TW":"依收入審查的福利確保政府援助惠及最需要的人。"},{"en":"Critics argue that means-tested programs create stigma and reduce take-up.","zh-TW":"批評者認為，依收入審查的計畫會產生污名化並降低申請率。"}]', NULL, NULL, 4, 4204, NULL),
(4205, 'measurable', 'ˈmɛʒərəbəl', 'adjective', '{"zh-TW":["可衡量的；可測量的","有具體結果的"],"en":["able to be measured","quantifiable"]}', NULL, 'measurable results/measurable goals', '[{"en":"Set measurable goals for each quarter.","zh-TW":"為每個季度設定可衡量的目標。"}]', '{"verb":"measure","noun":"measurement","adverb":"measurably"}', NULL, 4, 4205, NULL),
(4206, 'measure', '/ˈmeʒər/', 'noun, verb', '{"zh-TW":["措施；測量","測量；衡量"],"en":["an action taken to achieve a purpose; size or amount","to find the size or amount of something"]}', NULL, 'take measures / safety measures / measure performance', '[{"en":"The government took measures to reduce pollution.","zh-TW":"政府採取了減少污染的措施。"},{"en":"We need to measure the effectiveness of the campaign.","zh-TW":"我們需要衡量這次活動的效果。"}]', '{"noun":"measure, measurement","verb":"measure","adjective":"measurable"}', NULL, 3, 4206, 154),
(4207, 'mechanism', '/ˈmekənɪzəm/', 'noun', '{"zh-TW":["機制；機構"],"en":["a system of parts working together; a process"]}', NULL, 'feedback mechanism / pricing mechanism / defense mechanism', '[{"en":"We need a mechanism for handling complaints.","zh-TW":"我們需要一套處理投訴的機制。"},{"en":"The pricing mechanism is determined by supply and demand.","zh-TW":"定價機制由供需決定。"}]', '{"noun":"mechanism","adjective":"mechanical","verb":"mechanize"}', NULL, 3, 4207, NULL),
(4208, 'medal', '/ˈmɛdəl/', 'noun', '{"zh-TW":["獎牌"],"en":["a flat piece of metal given as a prize"]}', NULL, 'gold medal / win a medal', '[{"en":"She won a gold medal at the Olympics.","zh-TW":"她在奧運會上贏得了金牌。"},{"en":"The team brought home three medals.","zh-TW":"隊伍帶回了三面獎牌。"}]', '{"noun2":"medalist"}', NULL, 2, 4208, NULL),
(4209, 'medalist', '/''medəlɪst/', 'noun', '{"zh-TW":["獎牌得主；獲獎者"],"en":["a person who has been awarded a medal, especially in a sporting event"]}', NULL, 'Olympic medalist / gold medalist / defending medalist', '[{"en":"The gold medalist was welcomed home with a parade.","zh-TW":"金牌得主以遊行的方式受到了家鄉的歡迎。"},{"en":"She is a three-time Olympic medalist in the long jump.","zh-TW":"她是跳遠項目的三屆奧運獎牌得主。"}]', '{"noun":"medal"}', NULL, 3, 4209, NULL),
(4210, 'media', '/ˈmiːdiə/', 'noun', '{"zh-TW":["媒體"],"en":["the main means of mass communication"]}', NULL, 'social media / media coverage / media outlet', '[{"en":"Social media has transformed how companies market products.","zh-TW":"社群媒體改變了公司行銷產品的方式。"},{"en":"The event received extensive media coverage.","zh-TW":"這個活動獲得了廣泛的媒體報導。"}]', '{"noun":"media, medium","adjective":"medial"}', NULL, 2, 4210, 393),
(4211, 'media literacy', '/ˈmiːdiə ˈlɪtərəsi/', 'noun', '{"zh-TW":["媒體素養"],"en":["the ability to critically evaluate and create media content"]}', NULL, 'promote media literacy / media literacy skills / media literacy education', '[{"en":"Media literacy education helps students identify misinformation.","zh-TW":"媒體素養教育幫助學生識別錯誤資訊。"},{"en":"Low media literacy makes populations vulnerable to propaganda.","zh-TW":"低媒體素養使民眾容易受到宣傳的影響。"}]', '{"adjective":"media-literate"}', NULL, 5, 4211, NULL),
(4212, 'media training', '/''miːdiə ˌtreɪnɪŋ/', 'noun', '{"zh-TW":["媒體培訓；媒體訓練"],"en":["coaching that prepares individuals for interviews, press conferences, and other media interactions"]}', NULL, 'receive media training / media training workshop / benefit of media training', '[{"en":"The new spokesperson received extensive media training before her first interview.","zh-TW":"新發言人在她的第一次採訪前接受了廣泛的媒體培訓。"},{"en":"Media training teaches executives how to deliver clear messages under pressure.","zh-TW":"媒體培訓教導高管如何在壓力下傳達清晰的信息。"}]', NULL, NULL, 5, 4212, NULL),
(4213, 'mediate', '/ˈmiːdieɪt/', 'verb', '{"zh-TW":["調解；斡旋"],"en":["to try to end a disagreement between parties"]}', NULL, 'mediate a dispute / mediate between', '[{"en":"A neutral party was brought in to mediate the dispute.","zh-TW":"引入了中立方來調解爭端。"},{"en":"She mediated between management and the union.","zh-TW":"她在管理層和工會之間進行調解。"}]', '{"noun":"mediation, mediator","verb":"mediate"}', NULL, 3, 4213, NULL),
(4214, 'mediation', '/ˌmiːdiˈeɪʃən/', 'noun', '{"zh-TW":["調解；斡旋"],"en":["a process where a neutral party helps resolve a dispute"]}', NULL, 'go to mediation / mediation process / employment mediation', '[{"en":"Mediation resolved the contract dispute without litigation.","zh-TW":"調解解決了合同糾紛，無需訴訟。"},{"en":"Both parties agreed to enter mediation to settle their differences.","zh-TW":"雙方同意進行調解以解決分歧。"}]', '{"verb":"mediate","noun":"mediator"}', NULL, 3, 4214, NULL),
(4215, 'mediator', '/ˈmiːdieɪtər/', 'noun', '{"zh-TW":["調解人；仲裁者"],"en":["a neutral party who helps resolve a dispute between two or more parties"]}', NULL, 'appoint a mediator / role of the mediator', '[{"en":"Both companies agreed to use a mediator to settle the contract dispute.","zh-TW":"兩家公司同意使用調解人解決合約糾紛。"},{"en":"A skilled mediator can prevent costly litigation.","zh-TW":"熟練的調解人可以防止代價高昂的訴訟。"}]', '{"verb":"mediate","noun2":"mediation"}', NULL, 3, 4215, NULL),
(4216, 'medical history', '/ˈmɛdɪkəl ˈhɪstəri/', 'noun', '{"zh-TW":["病史；醫療史"],"en":["a record of a person''s past medical conditions"]}', NULL, 'provide medical history / review medical history', '[{"en":"The doctor reviewed her medical history before the examination.","zh-TW":"醫生在檢查前查看了她的病史。"},{"en":"Always bring your medical history when seeing a new doctor.","zh-TW":"看新醫生時務必攜帶您的病史。"}]', NULL, NULL, 5, 4216, NULL),
