(4218, 'medical record', '/ˈmɛdɪkəl ˈrɛkərd/', 'noun', '{"zh-TW":["病歷；醫療記錄"],"en":["a document containing a patient''s health history"]}', NULL, 'update medical record / request medical record', '[{"en":"Your medical record contains your full health history.","zh-TW":"您的病歷包含您完整的健康史。"},{"en":"Please bring your medical records to the appointment.","zh-TW":"請攜帶您的病歷前往就診。"}]', NULL, NULL, 5, 4218, NULL),
(4219, 'medication', '/ˌmɛdɪˈkeɪʃən/', 'noun', '{"zh-TW":["藥物；藥品"],"en":["a drug or medicine taken to treat illness"]}', NULL, 'take medication / prescription medication', '[{"en":"She takes daily medication to control her blood pressure.","zh-TW":"她每天服藥來控制血壓。"},{"en":"Never stop taking medication without consulting your doctor.","zh-TW":"不要在未諮詢醫生的情況下停藥。"}]', '{"verb":"medicate","adjective":"medicated"}', NULL, 4, 4219, NULL),
(4220, 'mediocre', '/ˌmiːdiˈoʊkər/', 'adjective', '{"zh-TW":["平庸的；普通的"],"en":["of only average quality; not very good"]}', NULL, 'mediocre performance/results/quality', '[{"en":"Mediocre performance will not be tolerated.","zh-TW":"平庸的表現將不被容忍。"},{"en":"The product received mediocre reviews.","zh-TW":"該產品獲得了普通的評價。"}]', '{"noun":"mediocrity","adjective":"mediocre"}', NULL, 3, 4220, NULL),
