(4223, 'meet', '/miːt/', 'verb', '{"zh-TW":["見面；符合"],"en":["to come together with","to satisfy a requirement"]}', NULL, 'meet the deadline / meet expectations', '[{"en":"Can we meet tomorrow at 2?","zh-TW":"我們明天2點見面好嗎？"},{"en":"The product meets all safety standards.","zh-TW":"產品符合所有安全標準。"}]', '{"verb":"meet","noun":"meeting"}', NULL, 1, 4223, NULL),
(4224, 'meet targets', '/miːt ˈtɑːrɡɪts/', 'verb', '{"zh-TW":["達成目標；完成指標"],"en":["to achieve the goals set for performance or output"]}', NULL, 'consistently meet targets / fail to meet targets', '[{"en":"The sales team met all its quarterly targets for the first time.","zh-TW":"銷售團隊首次達成了所有季度目標。"},{"en":"Incentive bonuses are paid only when staff meet their individual targets.","zh-TW":"只有當員工達到個人目標時才發放績效獎金。"}]', NULL, NULL, 4, 4224, NULL),
(4225, 'meeting', 'ˈmiːtɪŋ', 'noun', '{"zh-TW":["會議；開會","集會"],"en":["a gathering to discuss something","an arranged encounter"]}', NULL, 'board meeting/team meeting', '[{"en":"The weekly meeting is on Monday morning.","zh-TW":"每週會議在週一上午舉行。"}]', '{"verb":"meet","adjective":"meeting-related"}', NULL, 3, 4225, 155),
(4226, 'meeting room', '/ˈmiːtɪŋ ruːm/', 'noun', '{"zh-TW":["會議室"],"en":["a room used for holding meetings"]}', NULL, 'book a meeting room / meeting room facilities', '[{"en":"Please book the meeting room in advance.","zh-TW":"請提前預訂會議室。"},{"en":"The meeting room is equipped with video conferencing tools.","zh-TW":"會議室配備了視訊會議工具。"}]', NULL, NULL, 4, 4226, NULL),
