(4228, 'memo', '/ˈmemoʊ/', 'noun', '{"zh-TW":["備忘錄"],"en":["a short written message used in business"]}', NULL, 'send/write a memo / internal memo', '[{"en":"The manager sent a memo to all staff.","zh-TW":"經理向全體員工發送了一份備忘錄。"},{"en":"Please refer to the attached memo for details.","zh-TW":"詳情請參閱附件備忘錄。"}]', '{"noun":"memo, memorandum"}', NULL, 1, 4228, NULL),
(4229, 'memorandum', '/ˌmɛməˈrændəm/', 'noun', '{"zh-TW":["備忘錄"],"en":["a written message in an office or organization"]}', NULL, 'send a memorandum / internal memorandum', '[{"en":"A memorandum was circulated to all staff regarding the policy change.","zh-TW":"一份備忘錄已發送給所有員工，說明政策變更。"},{"en":"The memorandum outlined the new expense reimbursement procedure.","zh-TW":"備忘錄概述了新的費用報銷程序。"}]', '{"plural":"memoranda","abbreviation":"memo"}', NULL, 4, 4229, NULL),
(4230, 'memorandum of understanding', '/ˌmɛmərˈændəm əv ˌʌndəˈstændɪŋ/', 'noun', '{"zh-TW":["諒解備忘錄"],"en":["a formal agreement between two parties that is not legally binding"]}', NULL, 'sign a memorandum of understanding / memorandum of understanding terms', '[{"en":"They signed a memorandum of understanding to begin collaboration.","zh-TW":"他們簽署了諒解備忘錄開始合作。"},{"en":"A memorandum of understanding outlines the key terms before a formal contract.","zh-TW":"諒解備忘錄在正式合約之前概述了關鍵條款。"}]', '{"abbreviation":"MOU"}', NULL, 5, 4230, NULL),
(4231, 'mens rea', '/menz ˈriːə/', 'noun', '{"zh-TW":["犯罪意圖；犯意"],"en":["the mental state required for criminal liability"]}', NULL, 'establish mens rea / criminal mens rea / lack of mens rea', '[{"en":"Conviction requires proof of both actus reus and mens rea.","zh-TW":"定罪需要證明犯罪行為和犯罪意圖兩者。"},{"en":"The defendant''s attorney argued a lack of mens rea for the alleged offense.","zh-TW":"被告律師主張被告對被指控的罪行缺乏犯意。"}]', NULL, NULL, 3, 4231, NULL),
(4232, 'mention', 'ˈmɛnʃən', 'verb', '{"zh-TW":["提及；提到","說到"],"en":["to refer to briefly","to bring up"]}', NULL, 'mention a concern/mention details', '[{"en":"Please mention any special requirements.","zh-TW":"請提及任何特殊要求。"}]', '{"noun":"mention","adjective":"mentioned"}', NULL, 3, 4232, 156),
(4233, 'mentor', '/ˈmɛntɔːr/', 'noun', '{"zh-TW":["導師；良師益友","導師；顧問","指導"],"en":["an experienced person who advises","to guide and advise"]}', NULL, 'find a mentor / mentor program; mentor program / find a mentor / mentor someone', '[{"en":"She became my mentor at work.","zh-TW":"她成為了我工作中的導師。"},{"en":"Every student is assigned a mentor.","zh-TW":"每位學生都被分配了一位導師。"},{"en":"Every new employee is assigned a mentor.","zh-TW":"每位新員工都會被分配一位導師。"},{"en":"She mentored several junior colleagues.","zh-TW":"她指導了幾位初級同事。"}]', '{"verb":"mentor","noun2":"mentorship","noun":"mentor, mentorship, mentoring"}', NULL, 2, 4233, NULL),
(4234, 'mentor program', '/ˈmentər ˈproʊɡræm/', 'noun', '{"zh-TW":["導師計劃"],"en":["a structured initiative pairing experienced staff with junior employees for development"]}', NULL, 'launch a mentor program / join a mentor program', '[{"en":"The mentor program helped junior staff develop faster.","zh-TW":"導師計劃幫助初級員工更快地發展。"},{"en":"Participation in the mentor program is voluntary but encouraged.","zh-TW":"參與導師計劃是自願的，但受到鼓勵。"}]', NULL, NULL, 5, 4234, NULL),
(4235, 'mentoring', '/ˈmentərɪŋ/', 'noun', '{"zh-TW":["導師制；輔導"],"en":["a relationship where an experienced person guides a less experienced one"]}', NULL, 'mentoring program / provide mentoring / peer mentoring', '[{"en":"The mentoring program paired junior employees with senior leaders.","zh-TW":"導師計劃將初級員工與資深領導人配對。"},{"en":"She credited her success to strong mentoring early in her career.","zh-TW":"她將成功歸功於職業生涯早期的良好輔導。"}]', '{"verb":"mentor","noun":"mentor"}', NULL, 3, 4235, NULL),
(4236, 'mentoring program', '/ˈmentərɪŋ ˈproʊɡræm/', 'noun', '{"zh-TW":["導師計劃；輔導計劃"],"en":["a structured program pairing less experienced individuals with mentors"]}', NULL, 'launch a mentoring program / mentoring program effectiveness', '[{"en":"The mentoring program helped junior staff develop leadership skills.","zh-TW":"導師計劃幫助初級員工發展了領導技能。"},{"en":"Participants in the mentoring program reported higher job satisfaction.","zh-TW":"參與導師計劃的人員報告了更高的工作滿意度。"}]', NULL, NULL, 5, 4236, NULL),
(4237, 'mentorship', '/ˈmentərʃɪp/', 'noun', '{"zh-TW":["指導；師徒關係"],"en":["a relationship where an experienced person guides a junior one"]}', NULL, 'mentorship program / provide mentorship / mentorship relationship', '[{"en":"The mentorship program pairs new staff with senior employees.","zh-TW":"師徒計劃將新員工與資深員工配對。"},{"en":"She credits her success to strong mentorship early in her career.","zh-TW":"她將成功歸功於職業生涯早期良好的指導。"}]', '{"noun":"mentor","verb":"mentor"}', NULL, 4, 4237, NULL),
(4238, 'menu', '/ˈmɛnjuː/', 'noun', '{"zh-TW":["菜單"],"en":["a list of dishes available in a restaurant"]}', NULL, 'browse the menu / set menu', '[{"en":"Please take a moment to look over our menu.","zh-TW":"請花一點時間瀏覽我們的菜單。"},{"en":"The seasonal menu changes every month.","zh-TW":"季節性菜單每月更換。"}]', NULL, NULL, 1, 4238, NULL),
(4239, 'merchandise', '/ˈmɜːrtʃəndaɪz/', 'noun', '{"zh-TW":["商品；貨物","推銷"],"en":["goods that are bought and sold","goods for sale","to promote the sale of goods"]}', '{"root":{"text":"merch","meaning":"trade (貿易)"},"suffix":{"text":"-andise","meaning":"collective (集合)"},"logic":"貿易的集合，即「商品」。"}', 'merchandise display / branded merchandise', '[{"en":"The store sells a wide range of merchandise.","zh-TW":"這家店販售各種商品。"},{"en":"All merchandise must be paid for before leaving.","zh-TW":"所有商品在離開前必須付款。"},{"en":"The store offers a wide range of merchandise.","zh-TW":"這家商店提供各種各樣的商品。"},{"en":"The products were merchandised effectively.","zh-TW":"產品被有效地推銷。"}]', '{"noun":"merchant","verb":"merchandise"}', NULL, 4, 4239, 394),
(4240, 'merchandising', '/ˈmɜːrtʃəndaɪzɪŋ/', 'noun', '{"zh-TW":["商品展示；銷售陳列"],"en":["the promotion of goods for sale in a store"]}', NULL, 'visual merchandising / merchandising strategy', '[{"en":"Good merchandising draws attention to high-margin products.","zh-TW":"良好的商品陳列吸引了對高利潤產品的注意。"},{"en":"The merchandising team redesigned the store layout.","zh-TW":"商品展示團隊重新設計了商店佈局。"}]', '{"verb":"merchandise","noun":"merchandiser"}', NULL, 5, 4240, NULL),
(4241, 'merge', '/mɜːrdʒ/', 'verb', '{"zh-TW":["合併；融合"],"en":["to combine or join together"]}', NULL, 'merge with / merge into / merge companies', '[{"en":"The two companies merged to form a larger corporation.","zh-TW":"兩家公司合併成為一家更大的企業。"},{"en":"The lanes merge ahead.","zh-TW":"前方車道合併。"}]', '{"noun":"merger","verb":"merge"}', NULL, 2, 4241, NULL),
(4242, 'merger', '/ˈmɜːrdʒər/', 'noun', '{"zh-TW":["合併；併購"],"en":["the combination of two or more companies into one"]}', NULL, 'merger and acquisition / a merger between', '[{"en":"The merger created the largest bank in the country.","zh-TW":"這次合併創造了全國最大的銀行。"},{"en":"Both boards approved the merger last Friday.","zh-TW":"雙方董事會上週五批准了合併案。"}]', '{"verb":"merge","adjective":"merged"}', NULL, 2, 4242, NULL),
(4243, 'merger and acquisition', '/ˈmɜːrdʒər ənd ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["併購"],"en":["the consolidation of companies through mergers or one company buying another"]}', NULL, 'pursue a merger and acquisition / merger and acquisition strategy', '[{"en":"The merger and acquisition activity in the sector increased last year.","zh-TW":"去年該行業的併購活動有所增加。"},{"en":"A successful merger and acquisition requires thorough due diligence.","zh-TW":"成功的併購需要徹底的盡職調查。"}]', '{"abbreviation":"M&A"}', NULL, 5, 4243, NULL),
(4244, 'merger arbitrage', '/ˈmɜːrdʒər ˈɑːrbɪtrɑːʒ/', 'noun', '{"zh-TW":["合併套利"],"en":["an investment strategy profiting from price differences in M&A transactions"]}', NULL, 'employ merger arbitrage / merger arbitrage fund', '[{"en":"Merger arbitrage funds profit from the spread between offer and market prices.","zh-TW":"合併套利基金從要約價格和市場價格之間的差價中獲利。"},{"en":"Merger arbitrage requires careful analysis of deal completion probabilities.","zh-TW":"合併套利需要對交易完成概率進行仔細分析。"}]', NULL, NULL, 5, 4244, NULL),
(4245, 'mergers and acquisitions', '/ˈmɜːrdʒərz ænd ˌækwɪˈzɪʃənz/', 'noun', '{"zh-TW":["合併與收購"],"en":["corporate transactions involving the combining of companies or acquisition of assets"]}', NULL, 'pursue mergers and acquisitions / mergers and acquisitions strategy', '[{"en":"The company''s mergers and acquisitions activity tripled over five years.","zh-TW":"公司的合併與收購活動在五年內增加了兩倍。"},{"en":"Mergers and acquisitions advisors are hired to negotiate deal terms.","zh-TW":"聘用合併與收購顧問來談判交易條款。"}]', '{"abbreviation":"M&A"}', NULL, 5, 4245, NULL),
(4246, 'merit', '/ˈmerɪt/', 'noun, verb', '{"zh-TW":["優點；功績","值得"],"en":["a good quality or feature","to deserve or be worthy of"]}', NULL, 'on merit / merit attention/consideration', '[{"en":"Each proposal will be judged on its own merit.","zh-TW":"每個提案將根據其本身的優點進行評判。"},{"en":"The idea merits further investigation.","zh-TW":"這個想法值得進一步研究。"}]', '{"noun":"merit","verb":"merit","adjective":"meritorious"}', NULL, 2, 4246, NULL),
(4247, 'meritocracy', '/ˌmerɪˈtɒkrəsi/', 'noun', '{"zh-TW":["精英政治；能力主義"],"en":["a system in which advancement depends on ability and talent"]}', NULL, 'promote meritocracy / meritocracy in education / critique of meritocracy', '[{"en":"Many believe meritocracy rewards effort, while others argue it reinforces privilege.","zh-TW":"許多人相信能力主義獎勵努力，而另一些人則認為它強化了特權。"},{"en":"A genuine meritocracy requires equal access to education and opportunity.","zh-TW":"真正的能力主義需要平等的教育和機會。"}]', '{"adjective":"meritocratic","noun":"meritocrat"}', NULL, 4, 4247, NULL),
(4248, 'meritorious', '/''merɪˌtɔːriəs/', 'adjective', '{"zh-TW":["有功績的；值得稱讚的"],"en":["deserving reward or praise; having merit"]}', NULL, 'meritorious service / meritorious achievement / meritorious conduct', '[{"en":"She received a meritorious service award for her outstanding contribution.","zh-TW":"她因其傑出貢獻而獲得了功績服務獎。"},{"en":"The judge praised the meritorious efforts of the volunteer organization.","zh-TW":"法官讚揚了志願組織的有功績努力。"}]', '{"adverb":"meritoriously","noun":"merit"}', NULL, 4, 4248, NULL),
(4249, 'message', 'ˈmɛsɪdʒ', 'noun', '{"zh-TW":["訊息；留言","要旨"],"en":["a spoken or written communication","the main point of something"]}', NULL, 'leave a message/key message', '[{"en":"I left a message with the receptionist.","zh-TW":"我留了一條留言給接待員。"}]', '{"verb":"message","adjective":"messaging"}', NULL, 3, 4249, NULL);